using System;using System.Drawing;using System.IO;using System.Windows.Forms;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.WinForms;
namespace Aster {
sealed class EmbeddedVideo:UserControl {
 readonly WebView2 web=new WebView2{Dock=DockStyle.Fill};readonly Label notice=new Label{Dock=DockStyle.Fill,Text="Preparing the in-app player…",TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.White,BackColor=Color.FromArgb(16,23,34)};readonly Button reload=new Button{Text="Reload player",AutoSize=true};bool initializing,initialized;readonly string profileDirectory;
