 public EmbeddedVideo(Action back,string profileFolder=null){profileDirectory=profileFolder??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Aster","VideoBrowser");Dock=DockStyle.Fill;var root=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(root);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};var close=new Button{Text="Back to alerts",AutoSize=true};close.Click+=(s,e)=>back();reload.Click+=async(s,e)=>{if(initialized)web.CoreWebView2.Navigate(PlayerUrl);else await InitializePlayer();};actions.Controls.Add(close);actions.Controls.Add(reload);actions.Controls.Add(new Label{Text="YouTube video · plays inside Aster · stops when you leave this page",AutoSize=true,Margin=new Padding(16,9,0,0)});root.Controls.Add(actions,0,0);var host=new Panel{Dock=DockStyle.Fill};host.Controls.Add(web);host.Controls.Add(notice);root.Controls.Add(host,0,1);Load+=async(s,e)=>await InitializePlayer();}
 async System.Threading.Tasks.Task InitializePlayer(){if(initializing||initialized||IsDisposed)return;initializing=true;reload.Enabled=false;try{string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Video");if(!File.Exists(Path.Combine(folder,"index.html")))throw new FileNotFoundException();string profile=profileDirectory;var environment=await CoreWebView2Environment.CreateAsync(null,profile);if(IsDisposed)return;await web.EnsureCoreWebView2Async(environment);if(IsDisposed)return;var core=web.CoreWebView2;core.Settings.AreDevToolsEnabled=false;core.Settings.AreDefaultContextMenusEnabled=false;core.Settings.IsStatusBarEnabled=false;core.Settings.AreDefaultScriptDialogsEnabled=false;core.Settings.IsWebMessageEnabled=false;core.PermissionRequested+=(s,e)=>e.State=CoreWebView2PermissionState.Deny;core.NewWindowRequested+=(s,e)=>{e.Handled=true;};core.DownloadStarting+=(s,e)=>e.Cancel=true;core.NavigationStarting+=(s,e)=>{if(!String.Equals(e.Uri,PlayerUrl,StringComparison.OrdinalIgnoreCase)){e.Cancel=true;notice.Text="This player stays inside Aster. Use Back to alerts to return.";}};core.NavigationCompleted+=(s,e)=>{if(e.IsSuccess)notice.Visible=false;else{notice.Text="The player page could not load. Select Reload player to try again.";notice.Visible=true;}};core.SetVirtualHostNameToFolderMapping("aster-player.example",folder,CoreWebView2HostResourceAccessKind.DenyCors);initialized=true;notice.Visible=false;core.Navigate(PlayerUrl);}catch(WebView2RuntimeNotFoundException){if(!IsDisposed)notice.Text="Microsoft Edge WebView2 Runtime is required for the in-app player.\r\nInstall it from Microsoft's WebView2 website, then reload.";}catch(Exception){if(!IsDisposed)notice.Text="The in-app player could not start. Extract the whole Aster folder\r\nand check access to the local video-browser profile, then reload.";}finally{initializing=false;if(!IsDisposed)reload.Enabled=true;}}
